{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/0"],
      "relevance": "상담사가 '자기가 쌓아 온 게 한 단어로 덮이는 느낌'이라고 반영한 발화는, 내담자가 '나는 특별한 사람이므로 보통 사람에게 적용되는 규칙이 나에게 적용되어서는 안 된다'는 핵심 신념을 가지고 있음을 보여줌. 인사팀이 3년 연속 1등이라는 성과를 빼고 '폭언'이라는 일반적 규정 용어만 적용한 것을 자신의 특별성을 부정하는 모욕으로 받아들이는 패턴과 직접 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0"],
      "relevance": "'보통 사람들과 같은 취급을 받으면 그저 그런 사람으로 전락한다'는 부정적 가정이, '3년 연속 1등 팀장에게 폭언이라는 단어를 쓰는 것 자체가 모욕'이라는 내담자의 반응에 그대로 나타남. 성과와 무관하게 일반 직원이 받는 규정을 적용받는 순간 특별함이 무너진다고 느낌."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/0"],
      "relevance": "'능력도 없는 사람들이 나를 평가하는 것은 참을 수 없다'는 태도가, 인사팀장이 실적을 내본 적 없는 위치에서 자신에게 징계·상담을 통보한 것을 모욕으로 받아들이는 반응과 일치함. 상담사가 그 감정을 반영한 발화에 대해 내담자가 '반응 좀 해주세요'라고 한 것도, 평가하는 측이 자신의 맥락을 인정해 주기를 요구하는 것과 연결됨."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0"],
      "relevance": "'상대의 자격을 문제 삼아 무력화함'이라는 대처 전략이, 내담자가 인사팀장의 지적 내용을 검토하기보다 '3년 연속 1등 만든 팀장에게 그 단어를 쓰는 것 자체가 모욕'이라고 상대의 자격을 문제 삼는 방식으로 나타나고 있음."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/0"],
      "relevance": "'성취를 반복적으로 언급하며 특별한 위치를 상기시킴'이라는 전략이, 내담자가 상담 첫 발화에서부터 '3년 연속 전사 1등'을 반복적으로 강조하는 방식으로 나타나고 있음. 상담사도 이 성과를 반영에 포함시킴."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": [],
      "relevance": "'평가받는 자리는 시간 낭비로 규정하고 형식적으로 임함'이라는 전략이, 내담자가 '뭘 상담받아야 할지 모르겠다', '시간만 채우면 되는 건지'라고 말하며 상담 자체를 깎아내리는 태도에서 나타남. 상담사가 '편하게 계셔도 괜찮다'고 하자 '그럼 뭘 해야 하냐'고 재차 요구하는 것도 이 전략의 연장."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "'손상된 한계' 영역이, 내담자가 인사팀의 규정·절차(상담 이수 권고)를 한계로 받아들이지 못하고 모욕으로 반응하는 데서 나타남. 성장 배경에서 어머니가 규칙 위반을 무마해 주고 교사들이 문제 삼지 않았던 경험이 한계를 경험할 기회를 박탈한 것과 연결됨."
    }
  ]
}

